<script setup lang="ts">
import { ref, watch, onBeforeUnmount } from 'vue'
import { ApiError, type LoginResponse } from '../client'
import { presentationApi, invalidateStorePresentation, type Specification } from '../presentation-client'
import CatalogImage from './CatalogImage.vue'

const props = defineProps<{ account: LoginResponse; product?: string; variants?: Array<{ sku_id: string; variant: string }> }>()
const emit = defineEmits<{ expired: []; close: []; working: [value: boolean] }>()
const images = ref<string[]>([]), specs = ref<Specification[]>([]), shipping = ref(''), aftercare = ref(''), intro = ref(''), phone = ref(''), hours = ref(''), logo = ref<string | null>(null), version = ref(0)
const loading = ref(false), busy = ref(false), error = ref(''), notice = ref(''), conflict = ref(false)
const variantImages = ref<Record<string, string>>({})
let generation = 0
async function load() { const g = ++generation; loading.value = true; error.value = ''; notice.value = ''; conflict.value = false
  try { if (props.product) { const p = await presentationApi.product(props.product, props.account.access_token); if (g !== generation) return; version.value = p.version; images.value = [...p.images]; variantImages.value = Object.fromEntries(Object.entries(p.variant_images ?? {}).filter(([variant]) => props.variants?.some(sku => sku.variant === variant))); specs.value = p.specifications.map(s => ({ ...s })); shipping.value = p.shipping_note; aftercare.value = p.aftercare_note }
    else { const p = await presentationApi.managedStore(props.account.access_token); if (g !== generation) return; version.value = p.version; intro.value = p.introduction; phone.value = p.contact_phone; hours.value = p.service_hours; logo.value = p.logo_id }
  } catch (e) { if (g === generation) fail(e) } finally { if (g === generation) loading.value = false }
}
function fail(e: unknown) { if (e instanceof ApiError && e.status === 401) emit('expired'); error.value = e instanceof ApiError ? e.message : '暂时无法保存，请重新读取后确认'; if (e instanceof ApiError && e.status === 409) conflict.value = true }
async function save() { if (busy.value || loading.value || conflict.value) return; const g = generation; busy.value = true; emit('working', true); error.value = ''; notice.value = ''
  try { const result = props.product ? await presentationApi.saveProduct(props.account.access_token, props.product, { expected_version: version.value, images: [...images.value], variant_images: Object.fromEntries(Object.entries(variantImages.value).filter(([, id]) => images.value.includes(id))), specifications: specs.value.map(s => ({ ...s })), shipping_note: shipping.value, aftercare_note: aftercare.value }) : await presentationApi.saveStore(props.account.access_token, { expected_version: version.value, introduction: intro.value, logo_id: logo.value, contact_phone: phone.value, service_hours: hours.value }); if (g === generation) { version.value = result.version; if (!props.product && 'store_id' in result) invalidateStorePresentation(result.store_id); notice.value = '资料已保存' } }
  catch (e) { if (g === generation) fail(e) } finally { if (g === generation) { busy.value = false; emit('working', false) } }
}
async function upload(event: Event) { const input = event.target as HTMLInputElement, file = input.files?.[0]; input.value = ''; if (!file || busy.value) return
  if (file.size > 2 * 1024 * 1024 || !['image/png', 'image/jpeg'].includes(file.type)) { error.value = '请选择2MB以内的PNG或JPEG图片'; return }
  const g = generation; busy.value = true; emit('working', true); error.value = ''; notice.value = ''
  try { const value = await presentationApi.upload(props.account.access_token, file); if (g !== generation) return; if (props.product) images.value.push(value.media_id); else logo.value = value.media_id; notice.value = '图片已上传，保存资料后展示' }
  catch (e) { if (g === generation) fail(e) } finally { if (g === generation) { busy.value = false; emit('working', false) } }
}
function move(index: number, delta: number) { const next = index + delta; if (next < 0 || next >= images.value.length) return; const value = images.value.splice(index, 1)[0]; images.value.splice(next, 0, value) }
watch(() => [props.product, props.account.access_token], () => { images.value = []; specs.value = []; logo.value = null; void load() }, { immediate: true })
onBeforeUnmount(() => { generation++; emit('working', false) })
</script>
<template><section class="presentation-editor" :aria-label="product ? '商品图片与详情' : '店铺资料'"><header><h2>{{ product ? '商品图片与详情' : '店铺资料' }}</h2><button :disabled="busy" @click="load">重新读取</button><button :disabled="busy" @click="emit('close')">关闭</button></header><p v-if="loading">正在读取资料…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
  <form v-if="!loading" @submit.prevent="save"><fieldset :disabled="busy"><template v-if="product"><div class="presentation-images"><article v-for="(id, index) in images" :key="id"><div><CatalogImage :id="id" :token="account.access_token" :name="`商品图片${index + 1}`" /></div><span>{{ index === 0 ? '主图' : `图片 ${index + 1}` }}</span><div class="presentation-actions"><button type="button" :disabled="index === 0" @click="move(index, -1)">前移</button><button type="button" :disabled="index === images.length - 1" @click="move(index, 1)">后移</button><button type="button" @click="images.splice(index, 1)">移除</button></div></article></div><label class="presentation-upload">上传商品图片<input type="file" accept="image/png,image/jpeg" :disabled="images.length >= 8" @change="upload" /></label><small>最多8张，PNG或JPEG，单张2MB以内</small><h3 v-if="variants?.length">款式图片</h3><label v-for="variant in variants" :key="variant.sku_id">{{ variant.variant }}<select v-model="variantImages[variant.variant]"><option :value="undefined">使用主图</option><option v-for="(id, i) in images" :key="id" :value="id">图片 {{ i + 1 }}</option></select></label><h3>规格参数</h3><div v-for="(spec, index) in specs" :key="index" class="presentation-spec"><input v-model="spec.name" :aria-label="`参数名${index + 1}`" placeholder="参数名称" required maxlength="40" /><input v-model="spec.value" :aria-label="`参数值${index + 1}`" placeholder="参数内容" required maxlength="160" /><button type="button" @click="specs.splice(index, 1)">移除</button></div><button type="button" :disabled="specs.length >= 20" @click="specs.push({ name: '', value: '' })">添加参数</button><label>配送说明<textarea v-model="shipping" maxlength="500" /></label><label>售后说明<textarea v-model="aftercare" maxlength="1000" /></label></template>
  <template v-else><div v-if="logo" class="presentation-logo"><CatalogImage :id="logo" :token="account.access_token" name="店铺头像" /></div><label class="presentation-upload">上传店铺头像<input type="file" accept="image/png,image/jpeg" @change="upload" /></label><button v-if="logo" type="button" @click="logo = null">恢复默认头像</button><label>店铺简介<textarea v-model="intro" maxlength="500" /></label><label>联系电话<input v-model="phone" type="tel" maxlength="32" /></label><label>营业时间<input v-model="hours" maxlength="80" placeholder="例如：周一至周五 9:00–18:00" /></label></template>
  <button class="presentation-save" :disabled="busy || conflict">{{ busy ? '正在保存…' : '保存资料' }}</button></fieldset></form></section></template>
<style scoped>.presentation-editor{margin:24px 0;padding:26px;background:#fffdf8;border:1px solid #dce3d7;border-radius:12px;color:#293d34}.presentation-editor header{display:flex;align-items:center;gap:14px}.presentation-editor h2{font-size:20px;flex:1}.presentation-editor h3{font-size:17px;margin:26px 0 14px}.presentation-editor button{font:inherit;font-size:14px;cursor:pointer;color:#205e50;border:1px solid #d3dece;background:white;border-radius:7px;padding:8px 12px}.presentation-editor label:not(.presentation-upload){display:grid;gap:8px;margin:20px 0}.presentation-editor :is(input:not([type=file]),textarea){font:inherit;box-sizing:border-box;width:100%;padding:11px;border:1px solid #cdd7c8;border-radius:7px}.presentation-editor textarea{min-height:90px;resize:vertical}.presentation-editor fieldset{border:0;padding:0;margin:0;min-width:0}.presentation-images{display:flex;gap:16px;flex-wrap:wrap}.presentation-images article{width:160px}.presentation-images article>div:first-child{height:130px;background:#f0f2eb;border-radius:8px;overflow:hidden}.presentation-images span{font-size:13px;display:block;margin:8px 0}.presentation-actions{display:flex;gap:5px}.presentation-actions button{font-size:12px;padding:5px 7px}.presentation-upload{position:relative;display:inline-block;overflow:hidden;border:1px solid #cdd9c8;padding:10px 16px;border-radius:8px;color:#205e50;margin:18px 8px 8px 0}.presentation-upload input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.presentation-editor small{font-size:12px;color:#72806f}.presentation-spec{display:grid;grid-template-columns:1fr 2fr auto;gap:12px;margin:12px 0}.presentation-logo{width:80px;height:80px;overflow:hidden;border-radius:50%}.presentation-editor .presentation-save{display:block;background:#205e50;color:white;margin-top:24px;padding:11px 24px}.presentation-editor [role=alert]{color:#a33e31}.presentation-editor button:disabled{opacity:.5;cursor:default}@media(max-width:600px){.presentation-editor{padding:18px}.presentation-spec{grid-template-columns:1fr}.presentation-editor header{flex-wrap:wrap}}</style>
